import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for online Softmax
online_softmax_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void online_softmax_kernel(const float* x, float* out, int batch_size, int num_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        float max_val = x[idx * num_features];
        for (int i = 1; i < num_features; ++i) {
            if (x[idx * num_features + i] > max_val) {
                max_val = x[idx * num_features + i];
            }
        }

        float sum_exp = 0.0f;
        for (int i = 0; i < num_features; ++i) {
            sum_exp += expf(x[idx * num_features + i] - max_val);
        }

        for (int i = 0; i < num_features; ++i) {
            out[idx * num_features + i] = expf(x[idx * num_features + i] - max_val) / sum_exp;
        }
    }
}

torch::Tensor online_softmax_cuda(torch::Tensor x) {
    auto batch_size = x.size(0);
    auto num_features = x.size(1);
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    online_softmax_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), batch_size, num_features);

    return out;
}
"""

online_softmax_cpp_source = (
    "torch::Tensor online_softmax_cuda(torch::Tensor x);"
)

# Compile the inline CUDA code for online Softmax
online_softmax = load_inline(
    name="online_softmax",
    cpp_sources=online_softmax_cpp_source,
    cuda_sources=online_softmax_source,
    functions=["online_softmax_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()
        self.online_softmax = online_softmax

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.online_softmax.online_softmax_cuda(x)
